<?php require_once 'config/app.php';$count=$conn->query("SELECT COUNT(*) c FROM users WHERE role='admin'")->fetch_assoc()['c'];$msg='';if($_SERVER['REQUEST_METHOD']==='POST' && !$count){$name=trim($_POST['name']);$email=trim($_POST['email']);$pass=$_POST['password'];if(strlen($pass)<8)$msg='Fjalëkalimi duhet të ketë së paku 8 karaktere.';else{$hash=password_hash($pass,PASSWORD_DEFAULT);$s=stmt($conn,'INSERT INTO users(full_name,email,password,role) VALUES(?,?,?,\'admin\')','sss',[$name,$email,$hash]);redirect('login.php?admin_created=1');}}?><!doctype html><html lang="sq"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Konfigurimi i administratorit</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="auth-page"><div class="auth-side"><div class="auth-brand">Auto<span>Care</span></div><h1>Konfiguroni<br>hapësirën tuaj.</h1><p>Krijoni llogarinë e parë të administratorit për të menaxhuar sistemin AutoCare.</p></div><div class="auth-box"><form class="auth-card" method="post"><h2>Konfigurimi i administratorit</h2><p><?= $count?'Ekziston tashmë një administrator. Fshini këtë skedar konfigurimi.':'Krijoni llogarinë e parë të administratorit.' ?></p><?php if($msg):?><div class="alert error"><?=e($msg)?></div><?php endif;?><?php if(!$count):?><div class="field"><label>Emri dhe mbiemri</label><input name="name" required></div><div class="field"><label>Emaili</label><input type="email" name="email" required></div><div class="field"><label>Fjalëkalimi (së paku 8 karaktere)</label><input type="password" name="password" minlength="8" required></div><button class="btn">Krijo administratorin</button><?php else:?><a class="btn" href="login.php">Shko te kyçja</a><?php endif;?></form></div></body></html>
